<script lang="ts">
	let { data } = $props();
	const engine=data.engine;
	const fmt=(value:any)=>value?new Date(value).toLocaleString():'Unknown';
	const humanize=(value:any)=>String(value||'event').replace(/^engine\./,'').replace(/[._-]+/g,' ').replace(/\b\w/g,(m)=>m.toUpperCase());
	const detailEntries=(value:any)=>value && typeof value==='object' && !Array.isArray(value) ? Object.entries(value) : [];
	const displayValue=(value:any)=>{
		if(value===null||value===undefined||value==='') return '—';
		if(typeof value==='object') { try{return JSON.stringify(value)}catch{return '[details]'} }
		return String(value);
	};
</script>
<svelte:head><title>{engine.name} Logs · OrbitFS Engine Host</title><meta name="robots" content="noindex,nofollow" /></svelte:head>
<div class="app">
	<header><a class="brand" href="/engines"><span class="mark">O</span><span><b>OrbitFS</b><small>Engine Host</small></span></a><div class="crumb"><a href="/configuration">Host configuration</a><span>/</span><a href={`/engines/${engine.id}`}>{engine.name}</a><span>/</span><b>Logs</b></div></header>
	<main>
		<div class="heading"><p class="eyebrow">ACTIVITY LOG</p><h1>{engine.fullName}</h1><p>Recent engine activity from the shared OrbitFS audit trail. User and workspace names are resolved where possible, sensitive detail fields are redacted server-side, and no separate filesystem log store is created.</p></div>
		<section class="summary"><div><small>ENTRIES</small><b>{data.logs.length}</b><span>latest 200 maximum</span></div><div><small>SOURCE</small><b>{engine.id==='mcp'?'MCP audit':'OrbitFS audit'}</b><span>shared backend</span></div><div><small>STORAGE</small><b>Supabase</b><span>no local log files</span></div><div><small>RUNTIME</small><b>{engine.engineState}</b><span>current engine state</span></div></section>
		<section class="panel">
			<div class="panel-head"><div><p class="eyebrow">RECENT ACTIVITY</p><h2>Latest events</h2></div><span class="pill">Newest first</span></div>
			{#if data.logs.length}
				<div class="logs">{#each data.logs as row}<article class="log"><div class="event-head"><div><span class="event-dot"></span><div><b>{humanize(row.type)}</b><small>{fmt(row.createdAt)}</small></div></div><code>{row.type || 'event'}</code></div><div class="context"><div><span>Workspace</span><b>{row.scopeName || 'Global'}</b>{#if row.scope}<small>{row.scope}</small>{/if}</div><div><span>Actor</span><b>{row.actorName || 'System'}</b>{#if row.actor}<small>{row.actor}</small>{/if}</div></div>{#if detailEntries(row.detail).length}<details><summary>Technical details <span>{detailEntries(row.detail).length} fields</span></summary><div class="detail-grid">{#each detailEntries(row.detail) as [key,value]}<div><span>{humanize(key)}</span><code>{displayValue(value)}</code></div>{/each}</div></details>{/if}</article>{/each}</div>
			{:else}<div class="empty"><b>No recorded engine events yet.</b><span>Actions such as setup, runtime control and OAuth changes will appear here.</span></div>{/if}
		</section>
		<div class="actions"><a href={`/engines/${engine.id}`}>Overview</a><a href={`/engines/${engine.id}/monitoring`}>Monitoring</a><a href={`/engines/${engine.id}/diagnostics`}>Diagnostics</a></div>
	</main>
</div>
