x}.event-head>div>div{display:grid;gap:3px}.event-head b{font-size:12px}.event-head small{font-size:9px;color:#697584}.event-head>code{font-size:8px;color:#655f78;background:#0a0e15;border:1px solid #222a35;padding:4px 6px;border-radius:6px}.event-dot{width:8px;height:8px;margin-top:4px;border-radius:50%;background:#8b5cf6}.context{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0}.context>div{border:1px solid #202833;background:#090e14;border-radius:9px;padding:9px;display:grid;gap:3px}.context span{font-size:8px;color:#626f7d;text-transform:uppercase}.context b{font-size:10px}.context small{font-size:8px;color:#586573;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}details{border:1px solid #202833;border-radius:9px;background:#080c11;overflow:hidden}summary{cursor:pointer;padding:9px 10px;font-size:9px;color:#9aa6b4;list-style:none}summary::-webkit-details-marker{display:none}summary span{color:#626f7d;margin-left:5px}.detail-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1px;background:#202833;border-top:1px solid #202833}.detail-grid>div{background:#080c11;padding:9px;display:grid;gap:4px;min-width:0}.detail-grid span{font-size:8px;color:#697584}.detail-grid code{font-size:9px;color:#aeb7c3;white-space:pre-wrap;word-break:break-word}.empty{padding:34px;text-align:center;color:#758190;font-size:11px;display:grid;gap:5px}.empty b{color:#aab4c1;font-size:12px}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.actions a{border:1px solid #35404e;background:#111821;color:#d1d8e1;border-radius:9px;padding:9px 12px;font-size:11px;font-weight:800;text-decoration:none}@media(max-width:760px){.summary{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){header{padding:0 16px}.crumb{display:none}main{padding:34px 16px 55px}.heading h1{font-size:31px}.summary,.context,.detail-grid{grid-template-columns:1fr}.event-head{align-items:flex-start;flex-direction:column;gap:6px}}
